"""Publish precise qualification scope without promoting toy training to a result."""
import hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'outputs'
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def main():
    source=OUT/'dcl_preflight_v2/summary.json';r=json.loads(source.read_text())
    assert r['status']=='PASS_NATIVE_DCL_CORE_ARITHMETIC_AND_32_DISCARDED_GPU_UPDATES' and r['discarded_native_optimizer_updates']==32 and r['formal_fits']==0
    text='# Native DCL core: qualified executable, no formal benchmark result\n\n'
    text+=f"The pinned53-file native core passed independent numerical checks and32 discarded native solver updates on {r['gpu']} with Torch{r['torch']}. Toy fitting took {r['fit_wall_seconds']:.6f}s; peak allocated CUDA memory was {r['peak_cuda_allocated_bytes']:,}bytes. These are small-fixture resource measurements, not estimates for the paper sweep.\n\n"
    text+='| Independent comparison | Maximum absolute error |\n|---|---:|\n'
    for c in r['numerical_checks']:text+=f"|{c['device']} native full-denominator loss versus NumPy|{c['loss_abs_error']:.6g}|\n|{c['device']} reference gradient versus analytic NumPy derivative|{c['reference_gradient_max_abs_error']:.6g}|\n"
    text+=f"|Native linear prediction versus NumPy|{r['linear_prediction_max_abs_error']:.6g}|\n|Native reciprocal-MSE switching logits versus NumPy|{r['native_switching_logit_max_abs_error']:.6g}|\n\n"
    text+=f"All{r['actual_training_pair_count']} actual training pairs respected trial boundaries and advanced by one time point. A tracing-only loader subclass returned native batches unchanged. The actual encoder layers were5->90->90->30->3, with {r['parameter_count']} total encoder/dynamics parameters. The native Offset1ModelMLP ignores hidden_dim/num_layers configuration fields; no replacement architecture was introduced.\n\n"
    text+='Changing only the supplied next target changes the preferred native switching mode for all7 arithmetic-fixture examples. This verifies the documented retrospective interface; it is not evidence of poor causal forecasting or an accusation of leakage in the original identification task. Existing Markov switching and ordinary HMM/SLDS mechanisms remain required controls.\n\n'
    text+='Execution provenance: direct raw-GitHub requests from the server failed through both Python and native Windows clients. The connected GitHub service supplied the pinned public source through a RAM-only relay; all53 Git blobs were verified before use. No local result file was written. A separate project venv installed only lightweight typing dependencies over the existing shared Torch runtime. The RP/JAX environment, global packages and drivers were not changed. The downloaded public DCL catalog remains metadata-only; no released signal file or database service was used.\n\n'
    text+='The earlier qualifier v1 was never executed; v2 tightened pair-index validation to cover all indices regardless of trailing dimensions before the single successful run. There were32 discarded updates in total,0 formal DCL fits,0 paper metrics and0 accepted research directions from this work. The32 finite toy losses and parameter changes verify execution only. They do not establish representation recovery, forecast quality, calibration or a method benefit. Runtime preparation, source/package versions, protocol, raw qualification receipt, and server artifact hashes are retained.\n\n'
    text+='Next decision: await the existing16-model C54 comparison. DCL is now an executable alternative if its input and task contract makes a subsequent failure attribution informative. Do not launch a full sweep merely because the core runs.\n\nRaw qualification summary SHA256: '+sha(source)+'\n'
    target=ROOT/'DCL_PREFLIGHT_REPORT54_V1.md';assert not target.exists();target.write_text(text,encoding='utf-8');print(json.dumps({'report_sha256':sha(target),'discarded_updates':32,'formal_fits':0}),flush=True)
if __name__=='__main__':main()
